package android.view;public class WindowInsetsController {public static final int APPEARANCE_LIGHT_STATUS_BARS=8,APPEARANCE_LIGHT_NAVIGATION_BARS=16;private Window window;public WindowInsetsController(Window w){window=w;}public void setSystemBarsAppearance(int a,int m){if((m&8)!=0)window.lightStatus=(a&8)!=0;if((m&16)!=0)window.lightNavigation=(a&16)!=0;}public int getSystemBarsAppearance(){return (window.lightStatus?8:0)|(window.lightNavigation?16:0);} }
